def numeric_matrix(
    frame: pd.DataFrame, columns: tuple[str, ...] = NUMERIC
) -> np.ndarray:
    if not columns or len(set(columns)) != len(columns):
        raise ValueError("Need unique ordered feature names")
    matrix = np.array(
        frame.loc[:, list(columns)].to_numpy(dtype=np.float64, na_value=np.nan),
        dtype=np.float64,
        copy=True,
        order="C",
    )
    if matrix.ndim != 2 or matrix.shape[1] != len(columns) or np.isinf(matrix).any():
        raise ValueError("Invalid numeric matrix")
    # Missing numeric values remain NaN for this audit; no global imputation.
    return matrix


@dataclass
class OnlineMoments:
    count: int = 0
    mean: float = 0.0
    m2: float = 0.0

    def update(self, values: np.ndarray) -> None:
        values = np.asarray(values, dtype=np.float64)
        if values.ndim != 1 or not np.isfinite(values).all():
            raise ValueError("Expected a finite one-dimensional observed batch")
        if values.size == 0:
            return
        batch_count = int(values.size)
        batch_mean = float(values.mean())
        centered = values - batch_mean
        batch_m2 = float(centered @ centered)
        total = self.count + batch_count
        delta = batch_mean - self.mean
        new_mean = self.mean + delta * (batch_count / total)
        new_m2 = self.m2 + batch_m2 + delta * delta * (self.count / total) * batch_count
        if not np.isfinite([new_mean, new_m2]).all():
            raise ValueError("Moment calculation overflow; state was not updated")
        self.count, self.mean, self.m2 = total, new_mean, new_m2

    def summary(self) -> dict:
        return {
            "observed": self.count,
            "mean": self.mean if self.count else None,
            "population_variance": self.m2 / self.count if self.count else None,
        }


def attach_audit_counts(rows: pd.DataFrame, lookup: pd.DataFrame) -> pd.DataFrame:
    if (
        rows["source_row"].duplicated().any()
        or rows["workclass"].isna().any()
        or lookup["workclass"].isna().any()
    ):
        raise ValueError(
            "Need unique source positions and explicit missing-key sentinel"
        )
    joined = rows.merge(
        lookup,
        on="workclass",
        how="left",
        sort=False,
        validate="many_to_one",
        indicator=True,
    )
    if (
        len(joined) != len(rows)
        or joined["source_row"].tolist() != rows["source_row"].tolist()
        or not joined["_merge"].eq("both").all()
    ):
        raise ValueError("Merge changed row identity or lookup coverage")
    return joined.drop(columns="_merge")

import math


def mean_absolute_error(labels, predictions):
    labels, predictions = list(labels), list(predictions)
    if not labels or len(labels) != len(predictions):
        raise ValueError("Expected equal, nonempty sequences")
    values = labels + predictions
    if not all(math.isfinite(value) for value in values):
        raise ValueError("Inputs must be finite")
    # Validate before zip: zip would silently discard unmatched rows.
    absolute_errors = [abs(y - p) for y, p in zip(labels, predictions)]
    return math.fsum(absolute_errors) / len(labels)


print(mean_absolute_error([1, 4], [2, 2]))

