import numpy as np


def mse(prediction, target):
    p, y = np.asarray(prediction, dtype=float), np.asarray(target, dtype=float)
    if p.ndim != 1 or p.shape != y.shape or p.size == 0:
        raise ValueError("Exact nonempty 1-D shape required")
    if not np.isfinite(p).all() or not np.isfinite(y).all():
        raise ValueError("Finite values required")
    result = float(np.mean(np.square(p - y)))
    if not np.isfinite(result):
        raise ValueError("Arithmetic overflow")
    return result


