import math


def merge_means(n_a, mean_a, n_b, mean_b):
    if n_a < 0 or n_b <= 0 or not all(math.isfinite(x) for x in [mean_a, mean_b]):
        raise ValueError("Need valid counts and finite means")
    return mean_a + (mean_b - mean_a) * (n_b / (n_a + n_b))


print(merge_means(2, 10.0, 8, 20.0))

import numpy as np


def checked_mse(p, y):
    p, y = np.asarray(p, dtype=float), np.asarray(y, dtype=float)
    if p.ndim != 1 or p.shape != y.shape or p.size == 0:
        raise ValueError("Exact nonempty 1-D shape required")
    if not np.isfinite(p).all() or not np.isfinite(y).all():
        raise ValueError("Finite values required")
    return float(np.mean((p - y) ** 2))


